package com.lyric.core

import org.junit.Assert.*
import org.junit.Test

/** Complete OCF ZIP publications, regenerated by scripts/create-epub-fixtures.py. */
class EpubFixtureTest {
    @Test fun realEpub2And3ResolvePackagesSpineAndEncodedNavigation() {
        for (name in fixtures) {
            val bytes = javaClass.getResourceAsStream("/epub/$name")!!.use { it.readBytes() }
            val book = EpubParser().parse(BytesSource(bytes, name))
            assertEquals(name, "Lyric tests", book.author)
            assertEquals(name, 2, book.chapters.size)
            assertEquals(name, listOf("一片叶子", "晴天目录"), book.toc.map { it.title })
            assertTrue(name, book.chapters[0].text.drop(book.toc[0].charOffset).startsWith("目标段落"))
            assertEquals(name, 1, book.toc.last().chapterIndex)
        }
    }
    companion object {
        val fixtures = listOf("epub2-root.epub", "epub2-nested.epub", "epub3-nested.epub", "epub3-literal-percent.epub")
    }
}
